// Calculate which follow-ups are needed based on lead status and last contact
const leads = $input.all();
const now = new Date();
const followUps = [];

for (const item of leads) {
  const lead = item.json;
  const lastContact = new Date(lead['Last Contact']);
  const daysSinceContact = Math.floor((now - lastContact) / (1000 * 60 * 60 * 24));
  const status = lead.Status;
  const leadScore = lead['Lead Score'];

  // Skip if no email/phone
  if (!lead.Email && !lead.Phone) continue;

  // NEW LEAD SEQUENCE (Days 1-7)
  if (status === 'Qualified' && daysSinceContact >= 2 && daysSinceContact < 3) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'new-lead-day2',
        daysSinceContact,
        subject: `Found ${lead.Name.split(' ')[0]}! 3 more perfect properties`,
        message: 'day2-new-properties'
      }
    });
  }
  else if (status === 'Qualified' && daysSinceContact >= 3 && daysSinceContact < 4) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'new-lead-day3',
        daysSinceContact,
        subject: `Ready to schedule viewings?`,
        message: 'day3-viewing-check'
      }
    });
  }
  else if (status === 'Qualified' && daysSinceContact >= 5 && daysSinceContact < 6) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'new-lead-day5',
        daysSinceContact,
        subject: `🏠 3 NEW listings in your range!`,
        message: 'day5-new-listings'
      }
    });
  }
  else if (status === 'Qualified' && daysSinceContact >= 7 && daysSinceContact < 8) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'new-lead-day7',
        daysSinceContact,
        subject: `Let's connect this week`,
        message: 'day7-call-reminder'
      }
    });
  }

  // VIEWING SCHEDULED/ACTIVE SEQUENCE (Days 1-30)
  else if ((status === 'Viewing Scheduled' || status === 'Active') && daysSinceContact >= 3 && daysSinceContact < 4) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'active-day3',
        daysSinceContact,
        subject: `Similar properties you might love`,
        message: 'active-similar-properties'
      }
    });
  }
  else if ((status === 'Viewing Scheduled' || status === 'Active') && daysSinceContact >= 7 && daysSinceContact < 8) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'active-day7',
        daysSinceContact,
        subject: `Questions about the homes you saw?`,
        message: 'active-questions-check'
      }
    });
  }
  else if ((status === 'Viewing Scheduled' || status === 'Active') && daysSinceContact >= 14 && daysSinceContact < 15) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'active-day14',
        daysSinceContact,
        subject: `Market update: 2 new listings in your range`,
        message: 'active-market-update'
      }
    });
  }
  else if ((status === 'Viewing Scheduled' || status === 'Active') && daysSinceContact >= 21 && daysSinceContact < 22) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'active-day21',
        daysSinceContact,
        subject: `Checking in`,
        message: 'active-call-check'
      }
    });
  }
  else if ((status === 'Viewing Scheduled' || status === 'Active') && daysSinceContact >= 30 && daysSinceContact < 31) {
    followUps.push({
      json: {
        ...lead,
        followUpType: 'active-day30',
        daysSinceContact,
        subject: `Still looking? 5 new listings in your market`,
        message: 'active-30day-update'
      }
    });
  }

  // COLD/STALE SEQUENCE (Every 2 weeks)
  else if (status === 'Cold' || (daysSinceContact >= 30 && leadScore !== 'HOT')) {
    // Send every 14 days
    if (daysSinceContact % 14 === 0 && daysSinceContact >= 30 && daysSinceContact <= 180) {
      followUps.push({
        json: {
          ...lead,
          followUpType: 'cold-biweekly',
          daysSinceContact,
          subject: `Market update for your area`,
          message: 'cold-market-update'
        }
      });
    }
  }
}

return followUps.length > 0 ? followUps : [{ json: { noFollowUps: true } }];

// Generate personalized follow-up email for NEW LEADS
